import json, pathlib, re, subprocess, sys
sys.path.insert(0, "scripts")
import fleet_state as F, harness_registry as H
mr = pathlib.Path("docs/missions/MODEL_ROUTING.md").read_text(encoding="utf-8")
note = "Note (F013): Launcher prompts give goal, resources, budget and acceptance checks; Claude Code runs delegate wide reading to the Haiku explorer subagent, receipts record subagent calls and their tokens, and the scope check rejects compiled-module and stdlib shadowing."
assert note in mr.splitlines(), "missing F013 routing note"
native = {"claude": {"opus", "fable", "sonnet", "haiku"}, "codex": {"sol", "terra", "luna"}, "agy": {"argon", "flash"}, "cursor": {"composer", "grok"}}
reg = H.load_registry()
for name, spec in reg["seat_specs"].items():
    assert spec[0] in native and set(spec[1:]) <= native[spec[0]], (name, spec)
for door, d in reg["doors"].items():
    assert d["provider"] in native, door
    if d["provider"] not in ("claude", "codex"):
        assert not re.search("opus|sonnet|haiku|gpt|anthropic|openai", door + " " + d["pool"]), (door, d)
    for fam in sorted(set().union(*native.values()) - native[d["provider"]]) + ["gpt-oss"]:
        assert not F.native_door(reg, door, fam), (door, fam)
fleet = json.loads(pathlib.Path("docs/missions/20261014-2a-foundation/fleet.json").read_text(encoding="utf-8"))
assert fleet["approval"]["status"] == "approved" and fleet["approval"]["approved_at"].startswith("2026-10-18"), fleet["approval"]
for name, seat in fleet["seats"].items():
    res = seat["approved_resolution"]
    assert res["provider"] in native and seat["family"] in native[res["provider"]], (name, seat)
    for door in seat["doors"]:
        assert reg["doors"][door]["provider"] == res["provider"] and F.native_door(reg, door, seat["family"]), (name, door)
    if res["provider"] == "agy":
        assert not re.search("claude|opus|sonnet|gpt", res["model"]), (name, res)
    assert seat["effort"] == res["effort"] == ("high" if name.startswith("brain") else "medium"), (name, seat["effort"])
assert fleet["seats"]["brain"]["approved_resolution"] == {"effort": "high", "model": "opus", "provider": "claude", "speed": "unknown"}
rows = [json.loads(x) for x in pathlib.Path("docs/missions/ledger.jsonl").read_text(encoding="utf-8").splitlines() if x.strip()]
for r in rows:
    if r.get("door"):
        assert reg["doors"][r["door"]]["provider"] == {"agent": "cursor"}.get(r["cli"], r["cli"]), (r["run_id"], r["door"], r["cli"])
for tok in ("## Native-only (owner 2026-10-18)", "A door never serves another vendor", "never a door fallback.", "| Brain and planning (up to high) |", "| Review (up to medium) |"):
    assert tok in mr, tok
for line in mr.splitlines():
    for cell in (line.split("|") if line.lstrip().startswith("|") else [line]):
        if re.search(r"\bagy\b", cell):
            assert not re.search(r"(?i)opus|sonnet|gpt-oss", cell), line
brain_sh = pathlib.Path("scripts/spawn-brain.sh").read_text(encoding="utf-8")
bp = brain_sh.split('PROMPT="You are the mission BRAIN', 1)[1].split("Your log: ${LOG_REL}.", 1)[0]
for tok in ("Goal for mission-init:", "Goal for review:", "Resources:", "Acceptance checks:", "Budget:", "explorer on Haiku"):
    assert tok in bp, ("brain prompt", tok)
assert "append" not in bp.lower(), "brain prompt still asks to append"
wp = [x for x in pathlib.Path("scripts/spawn-worker.sh").read_text(encoding="utf-8").splitlines() if x.startswith('PROMPT="Goal: ')]
assert len(wp) == 1, wp
for tok in ("Scope: ", "Budget: ", "Resources: ", "verification commands pass", "explorer on Haiku", "PROGRESS.md and features.json belong to the Front Desk"):
    assert tok in wp[0], ("worker prompt", tok)
fm = pathlib.Path(".claude/agents/explorer.md").read_text(encoding="utf-8").split("---")[1].splitlines()
assert "name: explorer" in fm and "model: haiku" in fm and "tools: Read, Grep, Glob" in fm, fm
assert subprocess.run(["git", "ls-files", "--error-unmatch", ".claude/agents/explorer.md"], capture_output=True).returncode == 0
own = json.loads(pathlib.Path("harness-manifest.json").read_text(encoding="utf-8"))["ownership"]
assert ".claude/agents" in own["install_payload_roots"] and ".claude/agents" in own["update_paths"]
print("ok")
